/// <summary>
/// MPJ_24248 Price Data Extract
/// </summary>
[ExtensionOf(tableStr(METInventTable))]
internal final class METInventTableMet_Extension
{
}

Method.Source:
    /// <summary>
    /// Table Update
    /// </summary>
    public void update()
    {
        boolean     fieldUpdated = false;

        if(this.ItemStatus != this.orig().ItemStatus)
        {
            fieldUpdated = true;
        }
        
        next update();

        if(fieldUpdated)
        {
            METPriceChangeEventProduct::metProcessTrackChange(InventTable::find(this.ItemId));
        }
    }
